   And (IFNULL(E.Emp_BankStatus,1)=BK.CITM_NUM And BK.CGrp_Id=1108)
   And  IFNULL(E.Emp_Loc       ,0)=LC.CItm_Id
   And  IFNULL(E.Emp_Nat       ,0)=NT.CItm_Id
   And  IFNULL(E.Emp_Educat    ,0)=ED.CItm_Id
   And  IFNULL(E.Emp_Job       ,0)=JB.CItm_Id
   And  IFNULL(E.Emp_Dept      ,0)=DP.CItm_Id
   And  IFNULL(E.Emp_Sect      ,0)=SE.CItm_Id
