   And  IFNULL(E.Emp_Spc1      ,0)=S1.CItm_Id
   And  IFNULL(E.Emp_Spc2      ,0)=S2.CItm_Id
   And  IFNULL(E.Emp_Spc3      ,0)=S3.CItm_Id
   And  IFNULL(E.Emp_Spc4      ,0)=S4.CItm_Id
   And  ST.Lang_Id=SX.Lang_Id
