CREATE OR REPLACE VIEW Emp_VMChngeSal AS
SELECT
       M.CSal_ID    , M.CSal_Num  , M.CSal_Date, M.CSal_DocN , M.CSal_DocD,
       M.CSal_Perc  , M.CSal_Amt  , M.CSal_Min , M.CSal_Max  , M.CSal_Rem ,
