       MM.Loan_EDate , MM.Loan_TAmt, MM.Loan_MAmt, MM.Loan_BAmt  ,
       MM.Loan_Rem   ,
       EE.Emp_Name||' ['||To_Char(MM.Loan_SDate,'DD-MM-YYYY')||'-'||To_Char(MM.Loan_EDate,'DD-MM-YYYY')||'] {'||MM.Loan_TAmt||'-'||MM.Loan_MAmt||'}' Loan_Name,
